```pseudocode
// Input:
//   - I(x,λ)  : initial intensity distribution (mu, lambda)
//   - S(x)    : source term (mu)
//   - f(x,θ,φ) : phase function (mu, theta, phi)
//   - G(x,θ,φ) : scattering coefficient (mu, theta, phi)
//   - ρ(x,θ,φ) : reflection coefficient (mu, theta, phi)
//   - μ(x,λ)  : absorption coefficient (mu, lambda)
//   - Δx    : spatial step size
//   - Δλ    : spectral step size

// Output:
//   - I'(x,λ) : updated intensity distribution

function RTE(I, S, f, G, ρ, μ, Δx, Δλ)
    // Loop through all spatial and spectral discretization points
    for i in range(0, len(I)):
        x = i * Δx
        for j in range(0, len(I[i])):
            λ = j * Δλ
            // Compute the total absorption coefficient
            μ_total = μ(x, λ)
            // Compute the total scattering coefficient
            G_total = 0
            for θ in range(0, len(f)):
                for φ in range(0, len(f[θ])):
                    G_total += G(x, θ, φ) * f(θ, φ)
            // Compute the reflection coefficient
            ρ_total = 0
            for θ in range(0, len(ρ)):
                for φ in range(0, len(ρ[θ])):
                    ρ_total += ρ(x, θ, φ) * f(θ, φ)
            // Compute the radiative transfer term
            Q_total = S(x) + G_total * ∫I(x', λ) Δω(x, λ, x') dx'
            // Compute the updated intensity distribution
            I'(x, λ) = I(x, λ) * exp(-μ_total * Δx) + (Q_total / μ_total) * (1 - exp(-μ_total * Δx))
